import{_ as s,o as n,c as a,a2 as i}from"./chunks/framework.KobcctIO.js";const h=JSON.parse('{"title":"Gens-Horizon : Architecture du Moteur Cloud","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/horizon/overview.md","filePath":"fr/guide/horizon/overview.md"}'),o={name:"fr/guide/horizon/overview.md"};function t(l,e,r,p,c,d){return n(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="gens-horizon-architecture-du-moteur-cloud" tabindex="-1">Gens-Horizon : Architecture du Moteur Cloud <a class="header-anchor" href="#gens-horizon-architecture-du-moteur-cloud" aria-label="Permalink to &quot;Gens-Horizon : Architecture du Moteur Cloud&quot;">​</a></h1><div style="display:flex;gap:8px;margin:1rem 0;flex-wrap:wrap;"><img src="https://img.shields.io/badge/Moteur-CLI%20Headless-blue.svg" alt="Moteur"><img src="https://img.shields.io/badge/Protocole-IPC%20JSON%20Stream-green.svg" alt="Protocole"><img src="https://img.shields.io/badge/Stockage-Agnostique-orange.svg" alt="Stockage"></div><p><strong>Gens-Horizon</strong> (<code>C:\\dev\\Gens-Horizon</code>) est le moteur de synchronisation cloud déporté et autonome (« headless ») de l&#39;écosystème Gens. Conçu pour s&#39;exécuter en tâche de fond en tant que sous-processus de Gens-Launcher, il gère la synchronisation bidirectionnelle, le versionnement et la restauration des instances Minecraft avec les fournisseurs cloud majeurs (Google Drive, Dropbox, OneDrive).</p><hr><h2 id="_1-role-et-philosophie-de-conception" tabindex="-1">1. Rôle et Philosophie de Conception <a class="header-anchor" href="#_1-role-et-philosophie-de-conception" aria-label="Permalink to &quot;1. Rôle et Philosophie de Conception&quot;">​</a></h2><p>Dans la plupart des lanceurs traditionnels, la sauvegarde cloud se limite à compresser l&#39;intégralité du dossier du jeu dans une archive de plusieurs centaines de mégaoctets et à l&#39;envoyer sur un serveur. Cette méthode entraîne une consommation excessive de bande passante, des temps d&#39;attente prolongés et des risques de saturation d&#39;espace.</p><p>Gens-Horizon résout ce problème grâce à :</p><ul><li>Une synchronisation différentielle fine (<strong>Delta Sync</strong>) : seuls les blocs et fichiers altérés sont empaquetés et téléversés.</li><li>Une indépendance totale vis-à-vis de l&#39;interface graphique : le moteur peut être compilé sous forme de binaire autonome (<code>pkg</code>) ou exécuté en CLI pure.</li><li>Une conception agnostique du fournisseur cloud via le pattern Factory.</li><li>Une résilience accrue face aux pannes réseau et aux arrêts inopinés grâce à des verrous atomiques et un protocole de battement de cœur.</li></ul><hr><h2 id="_2-topologie-des-composants" tabindex="-1">2. Topologie des Composants <a class="header-anchor" href="#_2-topologie-des-composants" aria-label="Permalink to &quot;2. Topologie des Composants&quot;">​</a></h2><p>L&#39;architecture interne de Gens-Horizon s&#39;articule autour des modules suivants :</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                                  [ CLI / Launcher IPC ]</span></span>
<span class="line"><span>                                             |</span></span>
<span class="line"><span>                                             v</span></span>
<span class="line"><span>                                        index.js</span></span>
<span class="line"><span>                                             |</span></span>
<span class="line"><span>         +-----------------+-----------------+-----------------+</span></span>
<span class="line"><span>         |                 |                 |                 |</span></span>
<span class="line"><span>         v                 v                 v                 v</span></span>
<span class="line"><span>      check.js          sync.js          upload.js        rollback.js</span></span>
<span class="line"><span>         |                 |                 |                 |</span></span>
<span class="line"><span>         +-----------------+--------+--------+-----------------+</span></span>
<span class="line"><span>                                    |</span></span>
<span class="line"><span>                                    v</span></span>
<span class="line"><span>                            scanner.js (SHA-256)</span></span>
<span class="line"><span>                                    |</span></span>
<span class="line"><span>                                    v</span></span>
<span class="line"><span>                           provider.js (Factory)</span></span>
<span class="line"><span>                     /              |              \\</span></span>
<span class="line"><span>                    v               v               v</span></span>
<span class="line"><span>             providers/google  providers/dropbox  providers/onedrive</span></span>
<span class="line"><span>                                    |</span></span>
<span class="line"><span>        +---------------------------+---------------------------+</span></span>
<span class="line"><span>        |                           |                           |</span></span>
<span class="line"><span>        v                           v                           v</span></span>
<span class="line"><span>     lock.js                     Auth.js               cloud-operations.js</span></span>
<span class="line"><span>(Verrous atomiques)        (PBKDF2 / AES-GCM)        (Index &amp; Nettoyage)</span></span></code></pre></div><ul><li><strong><code>index.js</code></strong> : Routeur CLI principal. Intercepte <code>console.log/warn</code> pour rediriger les sorties textuelles des bibliothèques vers <code>process.stderr</code>, préservant la pureté du flux JSON sur <code>process.stdout</code>.</li><li><strong><code>scanner.js</code></strong> : Moteur de balayage local haute performance. Calcule les empreintes SHA-256 avec un limiteur de concurrence (<code>withConcurrency</code>) pour éviter l&#39;épuisement des descripteurs de fichiers (<code>EMFILE</code>).</li><li><strong><code>upload.js</code></strong> : Détecte les modifications locales par rapport au dernier état connu, crée une archive delta ciblée et l&#39;envoie sur le cloud.</li><li><strong><code>sync.js</code></strong> : Interroge l&#39;index distant, télécharge chronologiquement les deltas manquants et les applique localement.</li><li><strong><code>cloud-operations.js</code></strong> : Centralise la manipulation de l&#39;index distant et assure la purge automatique des sauvegardes en double ou obsolètes (<code>getCloudIndexAndCleanDuplicates</code>).</li><li><strong><code>rollback.js</code></strong> : Reconstruit l&#39;historique de manière déterministe pour restaurer une instance à n&#39;importe quel point de sauvegarde antérieur.</li><li><strong><code>zip-utils.js</code></strong> : Décompression ultra-optimisée en mémoire basée sur <code>yauzl</code>, intégrant une vérification stricte anti-Path Traversal et la validation de l&#39;en-tête binaire zip (<code>0x504B0304</code>).</li></ul><hr><h2 id="_3-protocole-de-communication-ipc-json" tabindex="-1">3. Protocole de Communication IPC JSON <a class="header-anchor" href="#_3-protocole-de-communication-ipc-json" aria-label="Permalink to &quot;3. Protocole de Communication IPC JSON&quot;">​</a></h2><p>Gens-Horizon communique avec Gens-Launcher via ses flux standard <code>stdout</code> et <code>stdin</code>. Tous les messages émis sur <code>stdout</code> sont strictement formatés en JSON unitaire :</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;type&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PROGRESS&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;step&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;COMPRESSING&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;value&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">65</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;instance&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Survie_Folia&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="types-d-evenements-supportes" tabindex="-1">Types d&#39;événements supportés : <a class="header-anchor" href="#types-d-evenements-supportes" aria-label="Permalink to &quot;Types d&#39;événements supportés :&quot;">​</a></h3><ul><li><code>PROGRESS</code> : Progression d&#39;étape (<code>SCANNING</code>, <code>COMPRESSING</code>, <code>UPLOADING</code>, <code>APPLYING_DELTA</code>).</li><li><code>INFO</code> : Messages d&#39;information textuels.</li><li><code>SUCCESS</code> : Notification de fin d&#39;opération avec métadonnées de synchronisation.</li><li><code>ERROR</code> : Signalement d&#39;anomalie avec code d&#39;erreur typé.</li><li><code>ROLLBACK_LIST</code> : Énumération chronologique des deltas disponibles pour restauration.</li><li><code>CHECK_RESULT</code> : Bilan comparatif entre l&#39;état local et l&#39;état distant.</li><li><code>CLOUD_LIST</code> : Inventaire complet des instances synchronisées sur le cloud.</li></ul>`,19)])])}const g=s(o,[["render",t]]);export{h as __pageData,g as default};
